curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for user in data['members']:
        if 'diego' in user.get('real_name', '').lower() or 'alvarez' in user.get('real_name', '').lower():
            print(json.dumps(user, indent=2))
else:
    print('Error:', data)
"

curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&types=private_channel" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(f\"ID: {ch['id']}, Name: {ch['name']}, Purpose: {ch.get('purpose', {}).get('value', 'N/A')}\")
else:
    print('Error:', data)
"

curl -s -X POST https://slack.com/api/users.conversations -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&user=U_DIEGO&types=private_channel" | python3 -c "
