curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&types=private_channel&exclude_archived=false&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        purpose = ch.get('purpose', {}).get('value', 'N/A')
        print(f\"ID: {ch['id']}, Name: {ch['name']}, Purpose: {purpose}, IsArchived: {ch.get('is_archived', False)}\")
    if data.get('response_metadata', {}).get('next_cursor'):
        print('Next cursor:', data['response_metadata']['next_cursor'])
else:
    print('Error:', data)
"

curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&types=public_channel,private_channel&exclude_archived=false&limit=1000" | python3 -c "
